import { pool } from "@workspace/db";

/**
 * Durable, provider-scoped Twilio reconciliation storage.
 * No customer invoice or payment is generated by this module.
 * The caller must verify that every provider page was fetched before marking complete.
 */
export type TwilioResource = "Calls" | "Messages";
export type ReconciliationRow = {
  sid: string;
  timestamp: string;
  from: string | null;
  to: string | null;
  price: string | null;
  currency: string | null;
};
export async function ensureTwilioReconciliationTables(): Promise<void> {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS ca_twilio_reconciliation_checkpoints (
      account_sid TEXT NOT NULL,
      billing_month CHAR(7) NOT NULL,
      resource TEXT NOT NULL CHECK (resource IN ('Calls','Messages')),
      next_page_uri TEXT,
      page_count INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending','running','complete','error')),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      PRIMARY KEY(account_sid,billing_month,resource)
    )`);
  await pool.query(`
    CREATE TABLE IF NOT EXISTS ca_twilio_reconciliation_records (
      account_sid TEXT NOT NULL,
      billing_month CHAR(7) NOT NULL,
      resource TEXT NOT NULL CHECK (resource IN ('Calls','Messages')),
      provider_sid TEXT NOT NULL,
      event_time TIMESTAMPTZ NOT NULL,
      from_number TEXT,
      to_number TEXT,
      price NUMERIC(18,8),
      currency TEXT,
      PRIMARY KEY(account_sid,resource,provider_sid)
    )`);
}

/**
 * Atomically persist a page and its continuation. A retry is idempotent.
 * Do not call with records outside the requested month; those indicate an
 * upstream date-filter problem and must fail closed.
 */
export async function persistTwilioPage(args: {
  accountSid: string;
  month: string;
  resource: TwilioResource;
  rows: ReconciliationRow[];
  nextPageUri: string | null;
}): Promise<void> {
  const { accountSid, month, resource, rows, nextPageUri } = args;
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) throw new Error("Invalid billing month");
  const start = Date.parse(month + "-01T00:00:00Z");
  const [year, mm] = month.split("-").map(Number);
  const end = Date.UTC(year, mm, 1);
  if (rows.some(r => !r.sid || !Number.isFinite(Date.parse(r.timestamp)) ||
    Date.parse(r.timestamp) < start || Date.parse(r.timestamp) >= end))
    throw new Error("Twilio page contains missing or out-of-period records");
  if (nextPageUri) {
    const url = new URL(nextPageUri, "https://api.twilio.com");
    if (url.protocol !== "https:" || url.hostname !== "api.twilio.com" ||
      url.pathname !== "/2010-04-01/Accounts/" + encodeURIComponent(accountSid) + "/" + resource + ".json" ||
      url.username || url.password || url.port || url.hash)
      throw new Error("Invalid Twilio continuation URL");
  }
  // Ensure a checkpoint cannot silently skip a page or be advanced by a
  // stale worker. Cross-instance execution is serialized by the worker lock.
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const checkpoint = await client.query(
      "SELECT status FROM ca_twilio_reconciliation_checkpoints WHERE account_sid=$1 AND billing_month=$2 AND resource=$3 FOR UPDATE",
      [accountSid, month, resource]);
    if (checkpoint.rows[0]?.status === "complete")
      throw new Error("Cannot append to completed reconciliation");
    for (const row of rows) {
      if (row.price != null && (!Number.isFinite(Number(row.price)) || !row.currency))
        throw new Error("Invalid Twilio price evidence");
      await client.query(`
        INSERT INTO ca_twilio_reconciliation_records
        (account_sid,billing_month,resource,provider_sid,event_time,from_number,to_number,price,currency)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
        ON CONFLICT (account_sid,resource,provider_sid) DO NOTHING`,
        [accountSid,month,resource,row.sid,row.timestamp,row.from,row.to,row.price,row.currency]);
    }
    await client.query(`
      INSERT INTO ca_twilio_reconciliation_checkpoints
        (account_sid,billing_month,resource,next_page_uri,page_count,status,updated_at)
      VALUES ($1,$2,$3,$4,1,$5,now())
      ON CONFLICT (account_sid,billing_month,resource)
      DO UPDATE SET next_page_uri=EXCLUDED.next_page_uri,
        page_count=ca_twilio_reconciliation_checkpoints.page_count+1,
        status=EXCLUDED.status,updated_at=now()`,
      [accountSid,month,resource,nextPageUri,nextPageUri ? "pending" : "complete"]);
    await client.query("COMMIT");
  } catch (e) {
    await client.query("ROLLBACK");
    throw e;
  } finally {
    client.release();
  }
}
export async function readTwilioCheckpoint(accountSid: string, month: string, resource: TwilioResource) {
  const { rows } = await pool.query(
    "SELECT next_page_uri, page_count, status, updated_at FROM ca_twilio_reconciliation_checkpoints WHERE account_sid=$1 AND billing_month=$2 AND resource=$3",
    [accountSid,month,resource]);
  return rows[0] ?? null;
}
